// One-hot state encoding:
//   A (0) --0--> B
//   A (0) --1--> A
//   B (0) --0--> C
//   B (0) --1--> D
//   C (0) --0--> E
//   C (0) --1--> D
//   D (0) --0--> F
//   D (0) --1--> A
//   E (1) --0--> E
//   E (1) --1--> D
//   F (1) --0--> C
//   F (1) --1--> D
//
// Derive the next-state signals Y2 and Y4 corresponding to signal y[1]
// and y[3].
module TopModule (
    input [5:0] y,
    input       w,
    output      Y1,
    output      Y3
);
    wire       A = (y == 6'b000001);
    wire       B = (y == 6'b000010);
    wire       C = (y == 6'b000100);
    wire       D = (y == 6'b001000);
    wire       E = (y == 6'b010000);
    wire       F = (y == 6'b100000);
    wire       Y2 = w ? E : D;
    wire       Y4 = w ? C : D;
    assign Y1 = A ? Y2 : (B ? Y2 : (C ? Y4 : (D ? Y4 : (E ? Y4 : Y4))));
    assign Y3 = A ? Y4 : (B ? Y2 : (C ? Y2 : (D ? Y4 : (E ? Y2 : Y4))));
endmodule

